/**
 * SEO contract — the indexable surface's rules, enforced on what actually
 * ships: the static layer generated by seo/build.mjs (homepage, /games/, the
 * quiz archive, grid answers, career path quizzes, sitemap, app shell).
 *
 * The generator runs once here against a stub of the built shell, from the
 * committed archive snapshot (no network). Every assertion below was a
 * production failure mode or a hand-check that would silently rot: titles past
 * the SERP budget, duplicate titles across hundreds of generated pages, a page
 * missing from the sitemap, a canonical on the www host, a Play button pointing
 * at a route the app doesn't have, the app shell becoming indexable.
 */
import { describe, it, expect, beforeAll } from "vitest";
import { mkdtempSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { generate } from "../../seo/build.mjs";
import {
  ROUTE_META,
  DEFAULT_META,
  TITLE_MAX,
  DESCRIPTION_MAX,
  resolveRouteMeta,
  canonicalFor,
  CANONICAL_OVERRIDES,
} from "@/lib/routeMeta";
import { isSeoPath } from "@/lib/seoPages";

const read = (p: string) => readFileSync(p, "utf8");

let dist = "";
let pages: string[] = [];
const html = (pagePath: string) => read(path.join(dist, pagePath, "index.html"));

beforeAll(async () => {
  dist = mkdtempSync(path.join(tmpdir(), "vq-seo-"));
  // The built shell differs from the source only in its hashed asset tags,
  // which the generator carries through untouched.
  const shell = read("index.html").replace(
    '<script type="module" src="/src/main.tsx"></script>',
    '<script type="module" crossorigin src="/assets/index-test.js"></script>\n    <link rel="stylesheet" crossorigin href="/assets/index-test.css">',
  );
  writeFileSync(path.join(dist, "index.html"), shell);
  const prev = process.env.VITE_CONVEX_URL;
  delete process.env.VITE_CONVEX_URL; // snapshot only — never the network in tests
  const result = await generate({ distDir: dist, log: () => {} });
  if (prev !== undefined) process.env.VITE_CONVEX_URL = prev;
  pages = result.pages.map((p) => p.path);
}, 60_000);

const pick = (h: string, re: RegExp) => h.match(re)?.[1]?.trim() ?? null;
const decode = (s: string) =>
  s.replace(/&amp;/g, "&").replace(/&quot;/g, '"').replace(/&lt;/g, "<").replace(/&gt;/g, ">");
const title = (h: string) => {
  const t = pick(h, /<title>(.*?)<\/title>/s);
  return t === null ? null : decode(t);
};
const description = (h: string) => {
  const d = pick(h, /<meta name="description" content="(.*?)"/s);
  return d === null ? null : decode(d);
};
const canonical = (h: string) => pick(h, /<link rel="canonical" href="(.*?)"/s);

describe("generated static surface", () => {
  it("covers every section with a real number of pages", () => {
    expect(pages).toContain("/");
    expect(pages).toContain("/games/");
    expect(pages.filter((p) => p.startsWith("/games/")).length).toBeGreaterThanOrEqual(8);
    expect(pages.filter((p) => /^\/football-quiz\/\d{4}-\d{2}-\d{2}\/$/.test(p)).length).toBeGreaterThan(100);
    expect(pages.filter((p) => p.startsWith("/who-played-for/")).length).toBeGreaterThan(300);
    expect(pages.filter((p) => p.startsWith("/career-path-quiz/")).length).toBeGreaterThan(30);
  });

  it("keeps every title and description within the SERP budget", () => {
    for (const p of pages) {
      const h = html(p);
      const t = title(h);
      const d = description(h);
      expect(t, `${p} has no <title>`).toBeTruthy();
      expect(t!.length, `${p} title (${t!.length}): ${t}`).toBeLessThanOrEqual(TITLE_MAX);
      expect(d, `${p} has no description`).toBeTruthy();
      expect(d!.length, `${p} description is ${d!.length} chars`).toBeLessThanOrEqual(DESCRIPTION_MAX);
    }
  });

  it("gives every page a unique title and description", () => {
    const titles = pages.map((p) => title(html(p)));
    const descs = pages.map((p) => description(html(p)));
    expect(new Set(titles).size).toBe(titles.length);
    expect(new Set(descs).size).toBe(descs.length);
  });

  it("self-references a non-www canonical on every page", () => {
    for (const p of pages) {
      expect(canonical(html(p)), p).toBe(`https://verveq.com${p}`);
    }
  });

  it("has exactly one h1 on every page but the homepage (whose h1 is the landing's)", () => {
    for (const p of pages.filter((x) => x !== "/")) {
      expect((html(p).match(/<h1[\s>]/g) ?? []).length, p).toBe(1);
    }
    expect((html("/").match(/<h1[\s>]/g) ?? []).length).toBe(0);
    expect((read("src/pages/shell/ColdEntryScreen.tsx").match(/<h1[\s>]/g) ?? []).length).toBe(1);
  });

  it("ships only valid JSON-LD", () => {
    for (const p of pages) {
      for (const m of html(p).matchAll(/<script type="application\/ld\+json">(.*?)<\/script>/gs)) {
        expect(() => JSON.parse(m[1]), p).not.toThrow();
      }
    }
  });

  it("never references the www host", () => {
    for (const p of pages) expect(html(p), p).not.toContain("www.verveq.com");
  });

  it("keeps the app bundle on every page so Play needs no page load", () => {
    for (const p of pages) expect(html(p), p).toContain("/assets/index-test.js");
  });

  it("defers every app asset on static pages so first paint is the page's own HTML", () => {
    for (const p of pages.filter((x) => x !== "/")) {
      const h = html(p);
      expect(h, p).not.toContain('<script type="module"');
      expect(h, p).not.toContain("modulepreload");
      expect(h, p).not.toMatch(/<link rel="stylesheet" (crossorigin )?href="[^"]+"(?![^<]*<\/noscript>)/);
    }
  });

  it("points every Play button at a route the app actually has", () => {
    const app = read("src/App.tsx");
    for (const p of pages) {
      for (const m of html(p).matchAll(/class="seo-cta[^"]*" data-spa href="([^"?]+)/g)) {
        expect(app, `${p} → ${m[1]}`).toContain(`path="${m[1]}"`);
      }
    }
  });

  it("indexes only quiz days whose content is mostly new", () => {
    const days = pages.filter((p) => /^\/football-quiz\/\d{4}-/.test(p));
    const noindexed = days.filter((p) => html(p).includes('content="noindex, follow"'));
    expect(noindexed.length).toBeGreaterThan(0);
    expect(noindexed.length).toBeLessThan(days.length);
  });

  it("registers every generated page with the SPA (else the app renders its 404 over it)", () => {
    for (const p of pages.filter((x) => x !== "/")) expect(isSeoPath(p), p).toBe(true);
  });

  it("never publishes today's daily quiz", () => {
    const today = new Date().toISOString().slice(0, 10);
    expect(pages).not.toContain(`/football-quiz/${today}/`);
  });
});

describe("app shell", () => {
  it("is noindex and carries no canonical", () => {
    const shell = read(path.join(dist, "app-shell.html"));
    expect(shell).toContain('<meta name="robots" content="noindex, follow" />');
    expect(canonical(shell)).toBeNull();
    expect(shell).not.toContain('id="seo"');
  });
});

describe("sitemap ↔ generated pages", () => {
  let locs: string[] = [];
  beforeAll(() => {
    locs = [...read(path.join(dist, "sitemap.xml")).matchAll(/<loc>(.*?)<\/loc>/g)].map((m) => m[1]);
  });

  it("lists only non-www, absolute URLs", () => {
    for (const loc of locs) expect(loc.startsWith("https://verveq.com/"), loc).toBe(true);
  });

  it("lists every generated page and the legal pages, and nothing dead", () => {
    const paths = new Set(locs.map((l) => new URL(l).pathname));
    for (const p of pages) {
      const noindex = html(p).includes('<meta name="robots" content="noindex');
      // Indexable pages must be listed; noindex pages must not be.
      expect(paths.has(p), `${p} sitemap membership vs noindex`).toBe(!noindex);
    }
    expect(paths.has("/privacy")).toBe(true);
    expect(paths.has("/terms")).toBe(true);
    for (const p of paths) {
      if (p === "/privacy" || p === "/terms") {
        expect(existsSync(`public${p}/index.html`), p).toBe(true);
        continue;
      }
      expect(pages, `${p} in sitemap but not generated`).toContain(p);
    }
  });
});

describe("canonical host consolidation", () => {
  it("nginx 301s the www host to the apex, preserving path and query", () => {
    const conf = read("../deploy/nginx.conf");
    expect(conf).toContain("server_name www.verveq.com;");
    expect(conf).toContain("return 301 https://verveq.com$request_uri;");
  });

  it("nginx answers unknown paths with a real 404 and redirects relatively", () => {
    const conf = read("../deploy/nginx.conf");
    expect(conf).toContain("absolute_redirect off;");
    expect(conf).toMatch(/location @spa\s*{[\s\S]*?return 404;/);
    expect(conf).toMatch(/rewrite \^ \$spa_shell last;/);
    expect(conf).toMatch(/map \$uri \$spa_shell \{\s*default \/app-shell\.html;/);
  });
});

/**
 * Link-preview cards (VerveQ ONE P2.4). Previews never run the app, so the
 * card a shared /older or /draw link shows is whatever HTML nginx returns for
 * that path. This resolves each entry path the way nginx does — the
 * `$spa_route` gate, then the `$spa_shell` map — and reads the generated file.
 */
describe("entry-path link previews", () => {
  const conf = () => read("../deploy/nginx.conf");
  const mapBlock = (name: string) => {
    const m = conf().match(new RegExp(`map \\$uri \\$${name} \\{([\\s\\S]*?)\\n\\}`));
    if (!m) throw new Error(`nginx map $${name} not found`);
    const rules: Array<[RegExp, string]> = [];
    let fallback = "";
    for (const line of m[1].split("\n")) {
      const t = line.trim().replace(/;$/, "");
      if (!t || t.startsWith("#")) continue;
      const [key, value] = t.split(/\s+/);
      if (key === "default") fallback = value;
      else rules.push([new RegExp(key.replace(/^~/, "")), value]);
    }
    return (uri: string) => rules.find(([re]) => re.test(uri))?.[1] ?? fallback;
  };
  const og = (h: string, prop: string) =>
    pick(h, new RegExp(`<meta (?:property|name)="${prop.replace(/[.:]/g, "\\$&")}" content="(.*?)"`));

  const ENTRY_EXPECT: Record<string, string> = {
    "/older": "older",
    "/whos-older": "older",
    "/v2/whos-older": "older",
    "/letters": "letters",
    "/missing-letters": "letters",
    "/v2/missing-letters": "letters",
    "/weekend": "weekend",
    "/v2/weekend": "weekend",
    "/draw": "draw",
  };

  it("serves every entry path its own card", () => {
    const spaRoute = mapBlock("spa_route");
    const spaShell = mapBlock("spa_shell");
    for (const [uri, id] of Object.entries(ENTRY_EXPECT)) {
      expect(spaRoute(uri), `${uri} is not an SPA route in nginx`).toBe("1");
      const file = spaShell(uri);
      expect(file, uri).toBe(`/entry/${id}.html`);
      const h = read(path.join(dist, file));
      const image = `https://verveq.com/og/v2/${id}.png`;
      expect(og(h, "og:image"), uri).toBe(image);
      expect(og(h, "twitter:image"), uri).toBe(image);
      expect(og(h, "og:title"), uri).toBeTruthy();
      expect(og(h, "og:description"), uri).toBeTruthy();
      expect(og(h, "twitter:card"), uri).toBe("summary_large_image");
      expect(existsSync(`public/og/v2/${id}.png`), `${id}.png is not committed`).toBe(true);
      // Still the app: noindex shell with the bundle, so the game boots.
      expect(h, uri).toContain('<meta name="robots" content="noindex, follow" />');
      expect(h, uri).toContain("/assets/index-test.js");
      expect(h, uri).toContain('<div id="root"></div>');
    }
    // A trailing slash resolves the same way.
    expect(spaShell("/older/")).toBe("/entry/older.html");
  });

  it("keeps the entry cards distinct and everything else on the default card", () => {
    const spaShell = mapBlock("spa_shell");
    const images = Object.values(ENTRY_EXPECT).map((id) => og(read(path.join(dist, `entry/${id}.html`)), "og:image"));
    expect(new Set(images).size).toBe(4);
    for (const uri of ["/compete", "/v2/daily", "/v2/weekend/squad", "/olderx", "/drawing"]) {
      expect(spaShell(uri), uri).toBe("/app-shell.html");
    }
    const home = "https://verveq.com/og/v2/home.png";
    expect(og(read(path.join(dist, "app-shell.html")), "og:image")).toBe(home);
    expect(og(html("/"), "og:image")).toBe(home);
    expect(existsSync("public/og/v2/home.png")).toBe(true);
  });

  it("retires the head-to-head default copy", () => {
    for (const h of [read("index.html"), html("/"), read(path.join(dist, "app-shell.html"))]) {
      expect(h).not.toContain("Settle it");
      expect(h).not.toContain("/og/home.png");
      expect(h).toContain("Can you beat it?");
    }
  });
});

describe("SPA route metadata", () => {
  it("keeps every title and description within the SERP budget", () => {
    for (const [p, meta] of Object.entries(ROUTE_META)) {
      expect(meta.title.length, `${p}: ${meta.title}`).toBeLessThanOrEqual(TITLE_MAX);
      expect(meta.description.length, `${p} description`).toBeLessThanOrEqual(DESCRIPTION_MAX);
    }
  });

  it("gives every route a distinct title", () => {
    const titles = Object.values(ROUTE_META).map((m) => m.title);
    expect(new Set(titles).size).toBe(titles.length);
  });

  it("falls back to the homepage's own head values", () => {
    const home = html("/");
    expect(DEFAULT_META.title).toBe(title(home));
    expect(DEFAULT_META.description).toBe(description(home));
    expect(resolveRouteMeta("/does-not-exist")).toEqual(DEFAULT_META);
  });

  it("normalises a trailing slash", () => {
    expect(resolveRouteMeta("/compete/")).toEqual(ROUTE_META["/compete"]);
    expect(canonicalFor("/compete/")).toBe("https://verveq.com/compete");
  });

  it("builds non-www canonicals, deferring game routes to their static page", () => {
    expect(canonicalFor("/")).toBe("https://verveq.com/");
    expect(canonicalFor("/compete")).toBe("https://verveq.com/compete");
    expect(canonicalFor("/v2/daily")).toBe("https://verveq.com/games/daily-football-quiz/");
    for (const target of Object.values(CANONICAL_OVERRIDES)) {
      expect(pages, `${target} is not a generated page`).toContain(target);
    }
  });
});
